  PML.fp_ok fx' -> PML.parser_at M' P ps' -> PML.wf_ps ps' -> PML.win_ok M' LBo ps' -> PML.buf_bound ps' B -> PML.ec_at M' E 0 -> PML.ls_ok g M' -> PML.pcredit_x L cr' ps' kx bx ->
  PMS.not_retreated ps0 ps' -> PML.ps_more ps' = PML.ps_more ps0 -> PML.ws_ok ps' ->
  forall c' w', PMR.rm_match c' M' P ps' -> PMW.win_bytes M' ps' w' -> PMR.skip_whitespace c0 w0 = (c', w') -> w' = skipn (length w0 - length w') w0 ->
