(* [comment removed for export] *)
Lemma sinv_ptrans : forall M M' model model' cr cr' ps ps' spc scr,
  sinv M model cr ps ->
  L5C.hpres L LBo spc scr (PML.W_par P E) M M' -> sp - SS <= spc - scr -> spc <= sp -> 0 <= scr -> spc mod 16 = 0 ->
  model_but_vm model model' -> hi_heap HI (PML.ps_blocks ps' ++ LBo) cr' M' (m_vmmaps model') ->
  PML.parser_at M' P ps' -> PML.wf_ps ps' -> PML.ws_ok ps' -> PML.win_ok M' LBo ps' -> PML.buf_bound ps' B -> PML.ec_at M' E 0 -> PML.ls_ok g M' ->
