Definition lctx (n : nat) (fx : FPState) (R : bvmap 5 word) (M : mem) (model : Model) (cr : credit) (ps : PML.pstate) (q e b : Z) : Prop :=
  at_loop n /\ mu ps q e <= Z.of_nat (S n) /\ PML.ps_win ps = Some (q, e) /\ q < e /\ PML.fp_ok fx /\ sinvw M model cr ps /\ PML.ps_more ps = false /\
  getr R 2%bv = Z_to_bv 64 (sp - SWT.FRAME) /\ SWS.sw_live R P e /\ getr R 10%bv = Z_to_bv 64 q /\ SWS.sw_frame M sp r R0 /\ TK.keepsR SWS.KO7 R0 R /\
  L5.u8_at RSEGS M q b /\ 0 <= b <= 255.

Lemma bp_win : forall M model cr ps q e, sinv M model cr ps -> PML.ps_win ps = Some (q, e) -> 4096 <= q /\ e <= hl_ceil L.
Proof.
  intros M model cr ps q e SI Hw.
  destruct SI as (PA & _ & _ & WIN & _ & _ & _ & HH & _).
  pose proof (blk M model cr ps HH) as (_ & BF).
  unfold PML.win_ok in WIN. rewrite Hw in WIN. destruct WIN as (ch & Hch & H1 & H2 & _).
  destruct (BF (ch, 16384)) as (B0 & B1 & _ & _ & B4); [apply in_or_app; right; exact Hch|]. cbn [fst snd] in *. lia.
Qed.

Lemma bp_inv : forall n fx R M model cr ps q e b C q' (M3 : mem),
  lctx n fx R M model cr ps q e b -> PML.ps_st ps = 28 -> PML.ps_stack ps = PML.ST_ROOT :: C ++ [PML.ST_DONE] ->
  Forall PML.is_container C -> (length C <= 1024)%nat ->
  (q' = q + 1 /\ b = 10) \/ (q' = q /\ b <> 10) ->
  TK.samem KP M M3 -> mem_grows M M3 -> PML.u64 M3 (P + 200) q' -> PML.u8 M3 (P + 208) PML.ST_DONE ->
  PML.u64 M3 (P + 256) (PML.ps_sb ps + Z.of_nat (length (PML.ST_ROOT :: C))) ->
  sinvw M3 model cr (PSB.ps_upd ps PML.ST_DONE (PML.ps_more ps) (PML.ST_ROOT :: C) (Some (q', e))).
Proof.
  intros n fx R M model cr ps q e b C q' M3 LC Hst Hstk FC LC1 Hq' AG MG U200 U208 U256.
  destruct LC as (_ & _ & Hw & Hqe & _ & (SI & WI) & Hmore & _ & _ & _ & _ & _ & Hb & Hb8).
  pose proof lay as (Y1 & Y2 & Y3 & Y4 & Y5 & Y6 & Y7 & Y8 & Y9 & Y10 & Y11 & Y12 & Y13).
  pose proof (bp_win M model cr ps q e SI Hw) as (W1 & W2).
  assert (KPh : forall a, 4096 <= a < hl_ceil L -> KP a) by (intros a Ha; unfold KP; lia).
  pose proof SI as SI0. destruct SI0 as (PA & WF & WS & _ & _ & _ & _ & _ & _ & _ & _ & BB & _).
  split.
  - apply (sinv_upd M M3 model cr ps PML.ST_DONE (PML.ST_ROOT :: C) [PML.ST_DONE] q q' e SI AG MG Hw); [lia | exact U200 | exact U208 | exact U256 | exact Hstk | | | ].
    + destruct WF as (F1 & F2 & _ & F4 & _). split; [exact F1|]. split; [exact F2|]. split; [cbn [PSB.ps_upd PML.ps_stack length]; lia|]. split; [exact F4|].
      exists C, []. split; [cbn [PSB.ps_upd PML.ps_stack]; rewrite app_nil_r; reflexivity|]. split; [exact FC|]. cbn [PSB.ps_upd PML.ps_more]. rewrite Hmore. discriminate.
    + intros _. exists C. split; [exact FC|]. split; [exact LC1|]. split; [left; split; reflexivity|].
      destruct (WS Hmore) as (C0 & _ & _ & _ & HLV). exact HLV.
    + destruct BB as (BB1 & BB2). split; [|exact BB2]. unfold PML.winlen, PML.buf_need in *. rewrite Hw in BB1.
      cbn [PSB.ps_upd PML.ps_win PML.ps_buf PML.ps_more PML.ps_st PML.ps_sst]. rewrite Hmore in *. cbn [andb] in *. lia.
  - pose proof (winv_x M M3 model cr ps KP SI WI AG KPh ltac:(intros a Ha; unfold PKW.tokc in Ha; unfold KP; lia)) as WI3.
    destruct WI3 as (c & w & WB & RM & SW & SUF).
    unfold PMW.win_bytes in WB. rewrite Hw in WB. destruct WB as (BA & Hlen & Hall).
    destruct w as [|b0 rs]; [cbn [length] in Hlen; lia|].
    assert (Hb0 : b0 = b).
    { apply (PKW.u8_eq M3 q b0 b).
      - pose proof (BA 0%nat ltac:(cbn [length]; lia)) as X. cbn [nth] in X. replace (q + Z.of_nat 0) with q in X by lia. exact X.
      - apply (TK.u8_samem KP M M3 q b AG); [lia | apply KPh; lia | exact Hb].
      - pose proof (Forall_inv Hall) as X. cbn beta in X. lia.
      - lia. }
    subst b0.
    destruct RM as ((C1 & C2 & C3 & C4 & C5) & _ & _).
    assert (Htop : PMR.top c = PML.ST_DONE) by (unfold PMR.top; rewrite C5, Hstk, app_comm_cons, last_last; reflexivity).
    assert (RMN : PMR.rm_match (PMR.set_st (PMR.pop c) (PMR.top c)) M3 P (PSB.ps_upd ps PML.ST_DONE (PML.ps_more ps) (PML.ST_ROOT :: C) (Some (q', e)))).
    { split; [|split].
      - unfold PMR.rm_core, PMR.set_st, PMR.pop, PMR.set_stack, PSB.ps_upd.
        cbn [PMR.c_st PMR.c_more PMR.c_done PMR.c_level PMR.c_stack PML.ps_st PML.ps_more PML.ps_done PML.ps_level PML.ps_stack].
        rewrite Htop, C5, Hstk, app_comm_cons, removelast_last. split; [reflexivity|]. split; [exact C2|]. split; [exact C3|]. split; [exact C4 | reflexivity].
      - cbn [PSB.ps_upd PML.ps_st]. intros X. unfold PML.ST_DONE, PML.ST_STRING in X. lia.
      - cbn [PSB.ps_upd PML.ps_st]. intros X. unfold PML.ST_DONE, PML.ST_NUMBER in X. lia. }
    destruct Hq' as [(-> & ->) | (-> & Hn)].
    + exists (PMR.set_st (PMR.pop c) (PMR.top c)), rs.
      split; [|split; [exact RMN|split]].
      * unfold PMW.win_bytes. cbn [PSB.ps_upd PML.ps_win]. split; [|split].
        -- intros i Hi. pose proof (BA (S i) ltac:(cbn [length]; lia)) as X. cbn [nth] in X. replace (q + Z.of_nat (S i)) with (q + 1 + Z.of_nat i) in X by lia. exact X.
        -- cbn [length] in Hlen. lia.
        -- exact (Forall_inv_tail Hall).
      * rewrite <- SW. destruct rs as [|b1 r1]; unfold PMR.skip_whitespace; cbn [PMR.c_st PMR.set_st]; rewrite ?Htop, ?C1, ?Hst; reflexivity.
      * assert (Hr : rs = skipn 1 (skipn (length w0 - length (10 :: rs)) w0)) by (rewrite <- SUF; reflexivity).
        rewrite skipn_skipn in Hr.
        transitivity (skipn (1 + (length w0 - length (10 :: rs))) w0); [exact Hr|].
        rewrite PKW.skipn_canon, <- Hr. reflexivity.
    + exists (PMR.set_st (PMR.pop c) (PMR.top c)), (b :: rs).
      split; [|split; [exact RMN|split]].
      * unfold PMW.win_bytes. cbn [PSB.ps_upd PML.ps_win]. split; [exact BA|]. split; [exact Hlen | exact Hall].
      * rewrite <- SW. unfold PMR.skip_whitespace; cbn [PMR.c_st PMR.set_st]; rewrite ?Htop, ?C1, ?Hst, (proj2 (Z.eqb_neq b 10) Hn); reflexivity.
      * exact SUF.
Qed.

Lemma br_pop : forall n fx R M model cr ps q e b, lctx n fx R M model cr ps q e b -> PML.ps_st ps = 28 ->
  forall q' (fx' : FPState) R' M', (q' = q + 1 /\ b = 10) \/ (q' = q /\ b <> 10) -> PML.fp_ok fx' -> getr R' 2%bv = Z_to_bv 64 (sp - 80) ->
  getr R' 1%bv = Z_to_bv 64 SWT.R_POP -> getr R' 10%bv = Z_to_bv 64 P -> SWS.sw_live R' P e -> TK.keepsR SWS.KO7 R R' -> L5.u64_at RSEGS M' (P + 200) q' ->
  TK.samem (SWS.KF P) M M' -> mem_grows M M' -> srealizes RSEGS SCFG (@PML.cfg fx' R' PML.PC_POP_STATE M' model) K.
Proof.
  intros n fx R M model cr ps q e b LC Hst q' fx1 R1 M1 Hq' Hfp1 H2a H1a H10a HL1 KO1 U200 AG1 MG1.
  pose proof LC as LC0.
  destruct LC0 as (IH & Hmu & Hw & Hqe & Hfp & (SI & WI) & Hmore & H2 & HL & H10 & FR & KO0 & Hb & Hb8).
  pose proof lay as (Y1 & Y2 & Y3 & Y4 & Y5 & Y6 & Y7 & Y8 & Y9 & Y10 & Y11 & Y12 & Y13).
  pose proof (bp_win M model cr ps q e SI Hw) as (W1 & W2).
  pose proof SI as (PA & WF & WS & WIN & VIS & EC & LS & HH & MOK & MBV & PC & BB & MORE & NR & FRm & DEFm).
  destruct (WS Hmore) as (C & FC & LCn & [(Hd & _) | (_ & Hstk)] & HLV); [exfalso; rewrite Hst in Hd; unfold PML.ST_DONE in Hd; lia|].
  pose proof PA as (_ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & PWIN & P208 & _ & _ & _ & _ & _ & _ & _ & _ & _ & P256 & _ & _ & _ & PDEF).
  destruct MOK as (MK1 & MK2 & _).
  assert (KPF : forall a, KP a -> SWS.KF P a) by (intros a Ha; unfold KP in Ha; unfold SWS.KF; lia).
  assert (AGP1 : TK.samem KP M M1) by (intros a Ha Hk; apply AG1; [exact Ha | exact (KPF a Hk)]).
  assert (P208a : PML.u8 M1 (P + 208) (PML.ps_st ps)).
  { apply (TK.u8_samem (SWS.KF P) M M1 (P + 208) _ AG1); [lia | unfold SWS.KF; lia | exact P208]. }
  assert (P256a : PML.u64 M1 (P + 256) (PML.ps_sb ps + Z.of_nat (length (PML.ps_stack ps)))).
  { apply (TK.u64_samem (SWS.KF P) M M1 (P + 256) _ AG1); [lia | intros i Hi; unfold SWS.KF; lia | exact P256]. }
  assert (SI1 : sinv M1 model cr (PSB.ps_upd ps (PML.ps_st ps) (PML.ps_more ps) (PML.ps_stack ps) (Some (q', e)))).
  { apply (sinv_upd M M1 model cr ps (PML.ps_st ps) (PML.ps_stack ps) [] q q' e SI AGP1 MG1 Hw);
      [lia | exact U200 | exact P208a | exact P256a | rewrite app_nil_r; reflexivity | exact WF | exact WS | ].
    destruct BB as (BB1 & BB2). split; [|exact BB2]. unfold PML.winlen, PML.buf_need in *. rewrite Hw in BB1.
    cbn [PSB.ps_upd PML.ps_win PML.ps_buf PML.ps_more PML.ps_st PML.ps_sst]. rewrite Hmore in *. cbn [andb] in *. lia. }
  pose proof SI1 as (PA1 & _).
  destruct (blk M model cr ps HH) as (_ & BF).
  destruct (BF (PML.ps_sb ps, PML.ps_scap ps)) as (S0 & S1 & _ & _ & S4); [apply in_or_app; left; unfold PML.ps_blocks; cbn [In]; right; left; reflexivity|].
  cbn [fst snd] in S0, S1, S4.
  assert (TP1 : getr R1 4%bv = Z_to_bv 64 PML.TP) by (rewrite (KO1 4%bv ltac:(ck_in)), (KO0 4%bv ltac:(ck_in)); exact R0tp).
  refine (POPSTATE P PML.ST_DONE (sp - 80) SWT.R_POP (PSB.ps_upd ps (PML.ps_st ps) (PML.ps_more ps) (PML.ps_stack ps) (Some (q', e))) (PML.ST_ROOT :: C)
            fx1 R1 M1 model K MK1 MK2 HK0 Hfp1 _ _).
  - split; [|split; [exact H10a|split; [exact PA1|split; [|split; [|split; [unfold PML.ST_DONE; lia|split]]]]]].
    + apply (CK.mk_entry L R1 M1 (sp - 80) SWT.R_POP 48 H1a (ra_ok_lit SWT.R_POP eq_refl) H2a TP1).
      apply mk_stk; [intros a Ha; apply MG1; exact (proj2 FRm a Ha) | rewrite Zminus_mod, Y2; reflexivity | lia | lia | lia].
    + cbn [PSB.ps_upd PML.ps_stack]. rewrite Hstk. apply app_comm_cons.
    + destruct OP as (O1 & O2 & O3). split; [lia|]. split; [lia | exact O3].
    + cbn [PSB.ps_upd PML.ps_sb]. lia.
    + cbn [PSB.ps_upd PML.ps_sb PML.ps_scap]. lia.
  - intros fx2 R2 M2 Hfp2 (A0x & U256) RP2 FB2 MG2.
    pose proof (TK2.frame_but_samem _ _ _ FB2) as AG2.
    assert (OUT2 : forall a, ~ (sp - 80 - 48 <= a < sp - 80) -> ~ (P + 256 <= a < P + 264) -> L5.outside [(sp - 80 - 48, 48); (P + 256, 8)] a).
    { intros a X1 X2 w Hw0. unfold L5.in_rng. destruct Hw0 as [<-|[<-|[]]]; cbn [fst snd]; lia. }
    assert (MG12 : mem_grows M M2) by (intros x Hx; apply MG2, MG1; exact Hx).
    assert (U200b : L5.u64_at RSEGS M2 (P + 200) q').
    { apply (TK.u64_samem _ M1 M2 (P + 200) q' AG2); [lia | intros i Hi; apply OUT2; lia | exact U200]. }
    assert (FR2 : SWS.sw_frame M2 sp r R0).
    { apply (SWS.sw_frame_x (fun a => SWS.KF P a /\ L5.outside [(sp - 80 - 48, 48); (P + 256, 8)] a) M M2 sp r R0).
      - apply (CK.samem_weaken2 (SWS.KF P) (L5.outside [(sp - 80 - 48, 48); (P + 256, 8)]) _ M M1 M2 AG1 AG2). intros a Ha. exact Ha.
      - lia.
      - intros i Hi. split; [unfold SWS.KF; lia | apply OUT2; lia].
      - exact FR. }
    assert (KOC : forall R3 : bvmap 5 word, TK.keepsR SWS.KO7 R2 R3 -> TK.keepsR SWS.KO7 R0 R3).
    { intros R3 KO3 x Hx. rewrite (KO3 x Hx), (SWS.ko7_rp _ _ RP2 x Hx), (KO1 x Hx). exact (KO0 x Hx). }
    assert (POST : forall M3 : mem, TK.samem (fun a => ~ (P + 208 <= a < P + 209)) M2 M3 -> mem_grows M2 M3 -> L5.u8_at RSEGS M3 (P + 208) PML.ST_DONE ->
              sinvw M3 model cr (PSB.ps_upd ps PML.ST_DONE (PML.ps_more ps) (PML.ST_ROOT :: C) (Some (q', e))) /\ SWS.sw_frame M3 sp r R0).
    { intros M3 AG3 MG3 U208.
      assert (AGK : TK.samem KP M M3).
      { intros a Ha Hk. unfold KP in Hk. rewrite (AG3 a Ha) by lia. rewrite (AG2 a Ha) by (apply OUT2; lia). apply AG1; [exact Ha | unfold SWS.KF; lia]. }
      assert (MG13 : mem_grows M M3) by (intros x Hx; apply MG3, MG12; exact Hx).
      assert (U200c : PML.u64 M3 (P + 200) q') by (apply (TK.u64_samem _ M2 M3 (P + 200) q' AG3); [lia | intros i Hi; lia | exact U200b]).
      assert (U256c : PML.u64 M3 (P + 256) (PML.ps_sb ps + Z.of_nat (length (PML.ST_ROOT :: C)))) by (apply (TK.u64_samem _ M2 M3 (P + 256) _ AG3); [lia | intros i Hi; lia | exact U256]).
      split; [exact (bp_inv n fx R M model cr ps q e b C q' M3 LC Hst Hstk FC LCn Hq' AGK MG13 U200c U208 U256c)|].
      apply (SWS.sw_frame_x (fun a => ~ (P + 208 <= a < P + 209)) M2 M3 sp r R0 AG3); [lia | intros i Hi; lia | exact FR2]. }
    apply (SWS.s_sw_r_pop FPM fx2 R2 M2 model K sp P e q' PML.ST_DONE r R0 MK1 MK2 Hfp2).
    + rewrite (SWS.sp_rp _ _ RP2). exact H2a.
    + split; [lia | exact Y2].
    + exact (SWS.sw_live_keep R1 R2 P e (SWS.sv_rp _ _ RP2) HL1).
    + exact A0x.
    + lia.
    + lia.
    + lia.
    + unfold PML.ST_DONE; lia.
    + exact U200b.
    + apply (L5.defined_grows M M2 _ _ MG12). apply (L5.defined_sub M P 272); [exact PDEF | lia | lia].
    + exact FR2.
    + exact Prok.
    + exact Y3.
    + intros Hqe' fx3 R3 M3 Hfp3 H2b SS6 KO3 U208 AG3 MG3.
      destruct (POST M3 AG3 MG3 U208) as (INV & _).
      apply (finish fx3 R3 M3 model cr (PSB.ps_upd ps PML.ST_DONE (PML.ps_more ps) (PML.ST_ROOT :: C) (Some (q', e))) Hfp3 INV).
      * intros c w WBw _. unfold PMW.win_bytes in WBw. cbn [PSB.ps_upd PML.ps_win] in WBw. destruct WBw as (_ & Hl & _).
        destruct w as [|x w]; [reflexivity | cbn [length] in Hl; lia].
      * apply SWS.rp_final; [rewrite H2b, R0sp; reflexivity | exact SS6 | exact (KOC R3 KO3)].
    + intros Hne fx3 R3 M3 Hfp3 H2b HL3 H10b KO3 U208 AG3 MG3.
      destruct (POST M3 AG3 MG3 U208) as (INV & FR3).
      assert (Hm2 : 2 * (e - q) + 1 <= Z.of_nat (S n)) by (unfold mu in Hmu; rewrite Hst in Hmu; exact Hmu).
      rewrite Nat2Z.inj_succ in Hm2.
      apply (IH fx3 R3 M3 model cr (PSB.ps_upd ps PML.ST_DONE (PML.ps_more ps) (PML.ST_ROOT :: C) (Some (q', e))) q' e).
      * unfold mu. cbn [PSB.ps_upd PML.ps_st]. change (if PML.ST_DONE =? 28 then 1 else 0) with 0. lia.
      * reflexivity.
      * lia.
      * exact Hfp3.
      * exact INV.
      * exact Hmore.
      * exact H2b.
      * exact HL3.
      * exact H10b.
      * exact FR3.
      * exact (KOC R3 KO3).
Qed.

Lemma bs_ss : forall (k : nat) c w, (length w <= k)%nat ->
  (exists m, snd (PMR.skip_space c w) = skipn m w) /\
  (snd (PMR.skip_space c w) = [] \/ (fst (PMR.skip_space c w) = c /\ exists b2 r2, snd (PMR.skip_space c w) = b2 :: r2 /\ PMR.is_ws b2 = false)).
Proof.
  induction k as [|k IH]; intros c w Hk.
  - destruct w as [|b rs]; [|cbn [length] in Hk; lia]. split; [exists 0%nat; reflexivity | left; reflexivity].
  - destruct w as [|b rs]; [split; [exists 0%nat; reflexivity | left; reflexivity]|].
    cbn [length] in Hk. cbn [PMR.skip_space].
    destruct ((b =? 32) || (b =? 9) || (b =? 10)) eqn:E1.
    + destruct (IH c rs ltac:(lia)) as ((m & Hm) & Hs). split; [exists (S m); exact Hm | exact Hs].
    + destruct (b =? 13) eqn:E2.
      * destruct rs as [|b2 r2].
        -- split; [exists 1%nat; reflexivity | left; reflexivity].
        -- cbn [length] in Hk. destruct (b2 =? 10) eqn:E3.
           ++ destruct (IH c r2 ltac:(lia)) as ((m & Hm) & Hs). split; [exists (S (S m)); exact Hm | exact Hs].
           ++ destruct (IH c (b2 :: r2) ltac:(cbn [length]; lia)) as ((m & Hm) & Hs). split; [exists (S m); exact Hm | exact Hs].
      * split; [exists 0%nat; reflexivity|]. right. split; [reflexivity|]. exists b, rs. split; [reflexivity|].
        unfold PMR.is_ws. rewrite E1, E2. reflexivity.
Qed.

Lemma bs_sw : forall c w, PMR.c_st c <> PML.ST_CR ->
  PMR.skip_whitespace (fst (PMR.skip_space c w)) (snd (PMR.skip_space c w)) = PMR.skip_space c w.
Proof.
  intros c w Hc. pose proof (bs_ss (length w) c w (le_n _)) as (_ & H).
  revert H. destruct (PMR.skip_space c w) as [c' w'] eqn:Ess. intros H. cbn [fst snd] in H |- *.
  destruct H as [-> | (-> & b2 & r2 & -> & Hw)].
  - reflexivity.
  - unfold PMR.skip_whitespace. rewrite (proj2 (Z.eqb_neq _ _) Hc). cbn [fst snd]. rewrite Hw. reflexivity.
Qed.

Lemma bs_after : forall c w,
  skipn (Z.to_nat (Z.of_nat (length w) - Z.of_nat (length (snd (PMR.skip_space c w))))) w = snd (PMR.skip_space c w).
Proof.
  intros c w. destruct (bs_ss (length w) c w (le_n _)) as ((m & Hm) & _). rewrite Hm.
  rewrite <- Nat2Z.inj_sub by (rewrite length_skipn; lia). rewrite Nat2Z.id. symmetry. apply PKW.skipn_canon.
Qed.

Lemma br_space : forall n fx R M model cr ps q e b, lctx n fx R M model cr ps q e b -> PML.ps_st ps <> 28 -> In b [9; 10; 13; 32] ->
  forall (fx' : FPState) R' M', PML.fp_ok fx' -> getr R' 2%bv = Z_to_bv 64 (sp - 80) -> getr R' 1%bv = Z_to_bv 64 SWT.R_SPACE ->
  getr R' 10%bv = Z_to_bv 64 P -> getr R' 11%bv = Z_to_bv 64 (P + 200) -> SWS.sw_live R' P e -> TK.keepsR SWS.KO7 R R' -> L5.u64_at RSEGS M' (P + 200) q ->
  TK.samem (SWS.KF P) M M' -> mem_grows M M' -> srealizes RSEGS SCFG (@PML.cfg fx' R' PML.PC_SKIP_SPACE M' model) K.
Proof.
  intros n fx R M model cr ps q e b LC Hst Hws fx1 R1 M1 Hfp1 H2a H1a H10a H11a HL1 KO1 U200 AG1 MG1.
  pose proof LC as LC0.
  destruct LC0 as (IH & Hmu & Hw & Hqe & Hfp & (SI & WI) & Hmore & H2 & HL & H10 & FR & KO0 & Hb & Hb8).
  pose proof lay as (Y1 & Y2 & Y3 & Y4 & Y5 & Y6 & Y7 & Y8 & Y9 & Y10 & Y11 & Y12 & Y13).
  pose proof (bp_win M model cr ps q e SI Hw) as (W1 & W2).
  pose proof SI as (PA & WF & WS & WIN & VIS & EC & LS & HH & MOK & MBV & PC & BB & MORE & NR & FRm & DEFm).
  assert (HstD : PML.ps_st ps = PML.ST_DONE).
  { destruct (WS Hmore) as (C & _ & _ & [(Hd & _) | (Hc & _)] & _); [exact Hd | exfalso; apply Hst; rewrite Hc; reflexivity]. }
  pose proof PA as (_ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & PWIN & P208 & _ & _ & _ & _ & _ & _ & _ & _ & _ & P256 & _ & _ & _ & PDEF).
  pose proof MOK as (MK1 & MK2 & MK3).
  destruct AP as (AP1 & AP2 & AP3).
  assert (KFh : forall a, 4096 <= a < hl_ceil L -> SWS.KF P a) by (intros a Ha; unfold SWS.KF; lia).
  assert (AGP1 : TK.samem KP M M1) by (intros a Ha Hk; apply AG1; [exact Ha | unfold KP in Hk; unfold SWS.KF; lia]).
  assert (P208a : PML.u8 M1 (P + 208) (PML.ps_st ps)).
  { apply (TK.u8_samem (SWS.KF P) M M1 (P + 208) _ AG1); [lia | unfold SWS.KF; lia | exact P208]. }
  assert (P256a : PML.u64 M1 (P + 256) (PML.ps_sb ps + Z.of_nat (length (PML.ps_stack ps)))).
  { apply (TK.u64_samem (SWS.KF P) M M1 (P + 256) _ AG1); [lia | intros i Hi; unfold SWS.KF; lia | exact P256]. }
  assert (SI1 : sinv M1 model cr ps).
  { assert (EQ : forall p0 : PML.pstate, PSB.ps_upd p0 (PML.ps_st p0) (PML.ps_more p0) (PML.ps_stack p0) (PML.ps_win p0) = p0) by (intros []; reflexivity).
    rewrite <- (EQ ps), Hw.
    apply (sinv_upd M M1 model cr ps (PML.ps_st ps) (PML.ps_stack ps) [] q q e SI AGP1 MG1 Hw);
      [lia | exact U200 | exact P208a | exact P256a | rewrite app_nil_r; reflexivity | exact WF | exact WS | ].
    destruct BB as (BB1 & BB2). split; [|exact BB2]. unfold PML.winlen, PML.buf_need in *. rewrite Hw in BB1.
    cbn [PSB.ps_upd PML.ps_win PML.ps_buf PML.ps_more PML.ps_st PML.ps_sst]. rewrite Hmore in *. cbn [andb] in *. lia. }
  pose proof SI1 as (PA1 & WF1 & WS1 & WIN1 & VIS1 & EC1 & LS1 & HH1 & _ & _ & PC1 & BB1 & _).
  pose proof (winv_x M M1 model cr ps (SWS.KF P) SI WI AG1 KFh ltac:(intros a Ha; unfold PKW.tokc in Ha; unfold SWS.KF; lia)) as WI1.
  destruct WI1 as (c & w & WB & RM & SW & SUF).
  pose proof WB as WB0. unfold PMW.win_bytes in WB0. rewrite Hw in WB0. destruct WB0 as (BA & Hlen & Hall).
  destruct w as [|b0 r0]; [cbn [length] in Hlen; lia|].
  assert (Hb0 : b0 = b).
  { apply (PKW.u8_eq M1 q b0 b).
    - pose proof (BA 0%nat ltac:(cbn [length]; lia)) as X. cbn [nth] in X. replace (q + Z.of_nat 0) with q in X by lia. exact X.
    - apply (TK.u8_samem (SWS.KF P) M M1 q b AG1); [lia | apply KFh; lia | exact Hb].
    - pose proof (Forall_inv Hall) as X. cbn beta in X. lia.
    - lia. }
  subst b0.
  pose proof RM as ((C1 & C2 & C3 & C4 & C5) & _ & _).
  assert (HcCR : PMR.c_st c <> PML.ST_CR) by (rewrite C1, HstD; unfold PML.ST_DONE, PML.ST_CR; lia).
  assert (Hisws : PMR.is_ws b = true) by (unfold PMR.is_ws; destruct Hws as [<-|[<-|[<-|[<-|[]]]]]; reflexivity).
  assert (SWss : PMR.skip_whitespace c (b :: r0) = PMR.skip_space c (b :: r0)).
  { unfold PMR.skip_whitespace. rewrite (proj2 (Z.eqb_neq _ _) HcCR). cbn [fst snd]. rewrite Hisws. reflexivity. }
  assert (TP1 : getr R1 4%bv = Z_to_bv 64 PML.TP) by (rewrite (KO1 4%bv ltac:(ck_in)), (KO0 4%bv ltac:(ck_in)); exact R0tp).
  refine (SKIPSPACE LBo cr (sp - 80) SWT.R_SPACE P V E B kx bx g ps (b :: r0) [] c fx1 R1 M1 model K HH1 MOK HK0 Hfp1 _ _).
  - refine (conj _ (conj _ (conj PA1 (conj WF1 (conj WIN1 (conj BB1 (conj VIS1 (conj EC1 (conj LS1 (conj G0 (conj PC1
              (conj _ (conj _ (conj _ (conj AP1 (conj AP2 (conj AP3 (conj WB RM)))))))))))))))))).
    + apply (CK.mk_entry L R1 M1 (sp - 80) SWT.R_SPACE (PMS.PF_SCR STRTOD_SCR) H1a (ra_ok_lit SWT.R_SPACE eq_refl) H2a TP1).
      apply mk_stk; [intros a Ha; apply MG1; exact (proj2 FRm a Ha) | rewrite Zminus_mod, Y2; reflexivity | lia | lia | lia].
    + split; [exact H10a|]. split; [exact H11a|]. split; [exact WS1|]. split; [rewrite Hmore; exact HstD|].
      exists q, e, b. split; [exact Hw|]. split; [exact Hqe|]. split; [|exact Hws].
      apply (TK.u8_samem (SWS.KF P) M M1 q b AG1); [lia | apply KFh; lia | exact Hb].
    + destruct OP as (O1 & O2 & O3). split; [lia|]. split; [lia | exact O3].
    + destruct OV as (O1 & O2 & O3). split; [lia|]. split; [lia | exact O3].
    + destruct OE as (O1 & O2 & O3). split; [lia|]. split; [lia | exact O3].
  - intros fx2 R2 M2 model2 LB2 cr2 LBk Wk Hfp2 POST RP2 HP2 MBV2 HH2.
    destruct POST as (ps2 & code & g2 & PA2 & WF2 & WIN2 & BB2 & EC2 & _ & LS2 & Hg2 & -> & -> & -> & PC2 & REL & RR).
    destruct REL as (-> & CONS & MORE2 & WS2 & ST2 & LV2).
    assert (Hg2' : g2 = g) by (destruct Hg2 as [-> | (_ & X)]; [reflexivity | exfalso; apply X; reflexivity]).
    subst g2.
    destruct RR as (_ & _ & RR). destruct (RR eq_refl) as (RM2 & _ & WB2).
    assert (HC := CONS). unfold PMS.consumed in HC. rewrite Hw in HC. revert HC.
    destruct (PML.ps_win ps2) as [[q2 e2]|] eqn:Hw2; [intros (-> & Hq2a & Hq2b) | intros []].
    assert (NR2 : PMS.not_retreated ps0 ps2) by exact (nr_step ps0 ps ps2 q q2 e NR Hw Hw2 ltac:(lia)).
    pose proof (sinv_ptrans M1 M2 model model2 cr cr2 ps ps2 (sp - 80) (PMS.PF_SCR STRTOD_SCR) SI1 HP2 ltac:(lia) ltac:(lia) ltac:(lia)
                  ltac:(rewrite Zminus_mod, Y2; reflexivity) MBV2 HH2 PA2 WF2 WS2 WIN2 BB2 EC2 LS2 PC2 MORE2 NR2) as (SI2 & AGs).
    assert (WI2 : winv M2 ps2).
    { exists (fst (PMR.skip_space c (b :: r0))), (snd (PMR.skip_space c (b :: r0))).
      split; [rewrite <- (bs_after c (b :: r0)); exact WB2|].
      split; [exact RM2|].
      split; [rewrite (bs_sw c (b :: r0) HcCR), <- SWss; exact SW|].
      destruct (bs_ss (length (b :: r0)) c (b :: r0) (le_n _)) as ((m & Hm) & _).
      assert (Hs : snd (PMR.skip_space c (b :: r0)) = skipn (m + (length w0 - length (b :: r0))) w0) by (rewrite Hm, <- skipn_skipn, <- SUF; reflexivity).
      transitivity (skipn (m + (length w0 - length (b :: r0))) w0); [exact Hs|].
      rewrite PKW.skipn_canon, <- Hs. reflexivity. }
    assert (FR2 : SWS.sw_frame M2 sp r R0).
    { apply (SWS.sw_frame_x (fun a => SWS.KF P a /\ sp - 80 <= a < sp) M M2 sp r R0).
      - apply (CK.samem_weaken2 (SWS.KF P) (fun a => sp - 80 <= a < sp) _ M M1 M2 AG1 AGs). intros a Ha. exact Ha.
      - lia.
      - intros i Hi. split; [unfold SWS.KF; lia | lia].
      - exact FR. }
    assert (KOC : forall R3 : bvmap 5 word, TK.keepsR SWS.KO7 R2 R3 -> TK.keepsR SWS.KO7 R0 R3).
    { intros R3 KO3 x Hx. rewrite (KO3 x Hx), (SWS.ko7_rp _ _ RP2 x Hx), (KO1 x Hx). exact (KO0 x Hx). }
    pose proof SI2 as (_ & _ & _ & _ & _ & _ & _ & _ & MOK2 & _).
    destruct MOK2 as (MK1' & MK2' & _).
    pose proof PA2 as (_ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & PWIN2 & _).
    rewrite Hw2 in PWIN2. destruct PWIN2 as (U2002 & _ & _).
    apply (SWS.s_sw_r_space FPM fx2 R2 M2 model2 K sp P e q2 r R0 MK1' MK2' Hfp2).
    + rewrite (SWS.sp_rp _ _ RP2). exact H2a.
    + split; [lia | exact Y2].
    + exact (SWS.sw_live_keep R1 R2 P e (SWS.sv_rp _ _ RP2) HL1).
    + lia.
    + lia.
    + lia.
    + exact U2002.
    + exact FR2.
    + exact Prok.
    + intros Hq2e fx3 R3 Hfp3 H2b SS6 KO3.
      apply (finish fx3 R3 M2 model2 cr2 ps2 Hfp3 (conj SI2 WI2)).
      * intros c3 w3 WBw _. unfold PMW.win_bytes in WBw. rewrite Hw2 in WBw. destruct WBw as (_ & Hl & _).
        destruct w3 as [|x w3]; [reflexivity | cbn [length] in Hl; lia].
      * apply SWS.rp_final; [rewrite H2b, R0sp; reflexivity | exact SS6 | exact (KOC R3 KO3)].
    + intros Hne fx3 R3 Hfp3 H2b HL3 H10b KO3.
      assert (Hst2 : PML.ps_st ps2 = PML.ST_DONE).
      { destruct ST2 as [X | (_ & X)]; [rewrite X; exact HstD | exfalso; unfold PMS.win_exhausted in X; rewrite Hw2 in X; lia]. }
      assert (Hm2 : 2 * (e - q) + 0 <= Z.of_nat (S n)) by (unfold mu in Hmu; rewrite HstD in Hmu; exact Hmu).
      rewrite Nat2Z.inj_succ in Hm2.
      apply (IH fx3 R3 M2 model2 cr2 ps2 q2 e).
      * unfold mu. rewrite Hst2. change (if PML.ST_DONE =? 28 then 1 else 0) with 0. lia.
      * exact Hw2.
      * lia.
      * exact Hfp3.
      * exact (conj SI2 WI2).
      * rewrite MORE2. exact Hmore.
      * exact H2b.
      * exact HL3.
      * exact H10b.
      * exact FR2.
      * exact (KOC R3 KO3).
Qed.

Lemma br_ret : forall n fx R M model cr ps q e b, lctx n fx R M model cr ps q e b -> PML.ps_st ps <> 28 -> PMR.is_ws b = false ->
  forall (fx' : FPState) R' M', PML.fp_ok fx' -> getr R' 2%bv = Z_to_bv 64 sp -> SWS.same_s06 R0 R' -> TK.keepsR SWS.KO7 R R' ->
  L5.u64_at RSEGS M' (P + 200) q -> TK.samem (SWS.KF P) M M' -> mem_grows M M' -> srealizes RSEGS SCFG (@PML.cfg fx' R' r M' model) K.
Proof.
  intros n fx R M model cr ps q e b LC Hst Hws fx' R' M' Hfp' H2' HSS Hk' C' Hsm Hg.
  destruct LC as (IH & Hmu & Hw & Hq & Hfp & Hsw & Hmore & H2 & Hlive & H10 & Hfr & Hko & Ub & Hbr).
  pose proof Hsw as (HS & HWV).
  pose proof HS as (HPA & HWF & HWS & HWIN & HVIS & HEC & HLS & HH & HMO & HMB & HPC & HBB & HMR & HNR & HFR & HND).
  pose proof lay as (Y1 & Y2 & Y3 & Y4 & Y5 & Y6 & Y7 & Y8 & Y9 & Y10 & Y11 & Y12 & Y13).
  pose proof HMO as (MO1 & MO2 & _).
  pose proof HWIN as HW0. unfold PML.win_ok in HW0. rewrite Hw in HW0. destruct HW0 as (ch & Hin & Hc1 & Hc2 & Hdef).
  pose proof (blk0 _ _ _ _ HH _ (in_or_app _ _ _ (or_intror Hin))) as (B0 & B1 & B2). cbn [fst snd] in B0, B1, B2.
  pose proof HPA as (_ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & PW & P208 & _ & _ & _ & _ & _ & _ & _ & _ & _ & P256 & _ & _ & _ & PD).
  rewrite Hw in PW. destruct PW as (P200 & P192 & Pqe).
  assert (HKP : TK.samem KP M M').
  { apply (TK.samem_weaken (SWS.KF P) KP M M' Hsm). intros a (A1 & A2 & A3 & A4). unfold SWS.KF. split; [exact A2 | intros X; apply A3; lia]. }
  assert (U208 : L5.u8_at RSEGS M' (P + 208) (PML.ps_st ps)).
  { apply (TK.u8_samem (SWS.KF P) M M' (P + 208) _ Hsm); [lia | unfold SWS.KF; lia | exact P208]. }
  assert (U256 : L5.u64_at RSEGS M' (P + 256) (PML.ps_sb ps + Z.of_nat (length (PML.ps_stack ps)))).
  { apply (TK.u64_samem (SWS.KF P) M M' (P + 256) _ Hsm); [lia | intros i Hi; unfold SWS.KF; lia | exact P256]. }
  assert (EQ0 : forall p0, PSB.ps_upd p0 (PML.ps_st p0) (PML.ps_more p0) (PML.ps_stack p0) (PML.ps_win p0) = p0) by (intros []; reflexivity).
  assert (EQ : PSB.ps_upd ps (PML.ps_st ps) (PML.ps_more ps) (PML.ps_stack ps) (Some (q, e)) = ps) by (rewrite <- Hw; exact (EQ0 ps)).
  assert (HS' : sinv M' model cr ps).
  { pose proof (sinv_upd M M' model cr ps (PML.ps_st ps) (PML.ps_stack ps) [] q q e HS HKP Hg Hw ltac:(lia) C' U208 U256 (eq_sym (app_nil_r _))
      ltac:(rewrite EQ; exact HWF) ltac:(rewrite EQ; exact HWS) ltac:(rewrite EQ; exact HBB)) as X.
    rewrite EQ in X. exact X. }
  assert (HWV' : winv M' ps).
  { apply (winv_x M M' model cr ps (SWS.KF P) HS HWV Hsm).
    - intros a Ha. unfold SWS.KF. lia.
    - intros a Ha. unfold PKW.tokc in Ha. unfold SWS.KF. lia. }
  apply (finish fx' R' M' model cr ps Hfp' (conj HS' HWV')).
  - intros c w HWB HRC. destruct HRC as (Hcs & _).
    pose proof HWB as HB. unfold PMW.win_bytes in HB. rewrite Hw in HB. destruct HB as (HBA & HBL & HBR).
    destruct w as [|b1 rest]; [cbn [length] in HBL; lia|].
    assert (U1 : L5.u8_at RSEGS M' q b1).
    { pose proof (HBA 0%nat ltac:(cbn [length]; lia)) as X. replace (q + Z.of_nat 0) with q in X by lia. exact X. }
    assert (Ub' : L5.u8_at RSEGS M' q b).
    { apply (TK.u8_samem (SWS.KF P) M M' q b Hsm); [lia | unfold SWS.KF; lia | exact Ub]. }
    pose proof (Forall_inv HBR) as Hb1. cbv beta in Hb1, Hbr.
    assert (Eb : b1 = b) by (apply (PKW.u8_eq M' q b1 b U1 Ub'); lia).
    subst b1.
    assert (Hcst : (PMR.c_st c =? 28) = false) by (apply Z.eqb_neq; rewrite Hcs; exact Hst).
    unfold PMR.skip_whitespace. cbv beta iota zeta. try unfold PML.ST_CR. rewrite Hcst.
    cbv beta iota zeta delta [snd fst]. rewrite Hws. reflexivity.
  - apply SWS.rp_final; [rewrite H2', R0sp; reflexivity | exact HSS | intros y Hy; rewrite (Hk' y Hy); exact (Hko y Hy)].
Qed.

Lemma loop_step : forall n, at_loop n -> at_loop (S n).
Proof.
  intros n IH. unfold at_loop.
  intros fx R M model cr ps q e Hmu Hw Hq Hfp Hsw Hmore H2 Hlive H10 Hfr Hko.
  pose proof Hsw as (HS & HWV).
  pose proof HS as (HPA & HWF & HWS & HWIN & HVIS & HEC & HLS & HH & HMO & HMB & HPC & HBB & HMR & HNR & HFR & HND).
  pose proof lay as (Y1 & Y2 & Y3 & Y4 & Y5 & Y6 & Y7 & Y8 & Y9 & Y10 & Y11 & Y12 & Y13).
  pose proof HMO as (MO1 & MO2 & _).
  pose proof HWIN as HW0. unfold PML.win_ok in HW0. rewrite Hw in HW0. destruct HW0 as (ch & Hin & Hc1 & Hc2 & Hdef).
  pose proof (blk0 _ _ _ _ HH _ (in_or_app _ _ _ (or_intror Hin))) as (B0 & B1 & B2). cbn [fst snd] in B0, B1, B2.
  pose proof HPA as (_ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & PW & P208 & _ & _ & _ & _ & _ & _ & _ & _ & _ & P256 & _ & _ & _ & PD).
  rewrite Hw in PW. destruct PW as (P200 & P192 & Pqe).
  destruct HWV as (c1 & w1 & HWB1 & HRM1 & HSK1 & HSF1).
  pose proof HWB1 as HB. unfold PMW.win_bytes in HB. rewrite Hw in HB. destruct HB as (HBA & HBL & HBR).
  destruct w1 as [|b rest]; [cbn [length] in HBL; lia|].
  assert (Ub : L5.u8_at RSEGS M q b).
  { pose proof (HBA 0%nat ltac:(cbn [length]; lia)) as X. replace (q + Z.of_nat 0) with q in X by lia. exact X. }
  pose proof (Forall_inv HBR) as Hbr. cbv beta in Hbr.
  assert (Hst : 0 <= PML.ps_st ps <= 255).
  { destruct (HWS Hmore) as (C & _ & _ & [(S1 & _) | (S1 & _)] & _); rewrite S1; unfold PML.ST_DONE, PML.ST_CR; lia. }
  destruct (u64_of_defined M (P + 160) ltac:(eapply (L5.defined_sub _ _ _ _ _ PD); lia)) as (v160 & R160 & C160).
  destruct (u64_of_defined M (P + 168) ltac:(eapply (L5.defined_sub _ _ _ _ _ PD); lia)) as (v168 & R168 & C168).
  destruct (u64_of_defined M (P + 176) ltac:(eapply (L5.defined_sub _ _ _ _ _ PD); lia)) as (v176 & R176 & C176).
  assert (LC : lctx n fx R M model cr ps q e b) by exact (conj IH (conj Hmu (conj Hw (conj Hq (conj Hfp (conj Hsw (conj Hmore (conj H2 (conj Hlive (conj H10 (conj Hfr (conj Hko (conj Ub Hbr))))))))))))).
  refine (SWSW.s_sw_loopw FPM fx R M model K sp P e q b (PML.ps_st ps) v160 v168 v176 q r R0 MO1 MO2 Hfp H2 spok Hlive H10 _ _ _ Hbr Hst R160 R168 R176 _ Ub P208 C160 C168 C176 P200 _ _ Hfr Prok Y3 _ _ _ _).
  all: try lia.
  all: try (eapply (L5.defined_sub _ _ _ _ _ PD); lia).
  - intros Hs. exact (br_pop n fx R M model cr ps q e b LC Hs).
  - intros Hs Hb'. exact (br_space n fx R M model cr ps q e b LC Hs Hb').
  - intros Hs Hb'. exact (br_ret n fx R M model cr ps q e b LC Hs Hb').
Qed.
Lemma loop_all : forall n, at_loop n.
Proof.
  induction n as [|n IH].
  - unfold at_loop. intros fx R M model cr ps q e Hmu Hw Hq. exfalso. unfold mu in Hmu. destruct (Z.eqb (PML.ps_st ps) 28); lia.
  - apply loop_step. exact IH.
Qed.

(* [comment removed for export] *)
Lemma run_ok : forall (fx : FPState) cr, PML.fp_ok fx -> sinvw M0 model0 cr ps0 -> getr R0 10%bv = Z_to_bv 64 P -> (PML.ps_more ps0 = true -> PMS.win_exhausted ps0) -> getr R0 1%bv = Z_to_bv 64 r ->
  srealizes RSEGS SCFG (@PML.cfg fx R0 PML.PC_SKIP_WS M0 model0) K.
Proof.
  intros fx cr Hfp Hsw H10 Hex H1.
  pose proof Hsw as (HS & HWV).
  pose proof HS as (HPA & HWF & HWS & HWIN & HVIS & HEC & HLS & HH & HMO & HMB & HPC & HBB & HMR & HNR & HFR & HND).
  pose proof lay as (Y1 & Y2 & Y3 & Y4 & Y5 & Y6 & Y7 & Y8 & Y9 & Y10 & Y11 & Y12 & Y13).
  pose proof HMO as (MO1 & MO2 & _).
  pose proof STK0 as (_ & _ & _ & _ & SD).
  pose proof HPA as (_ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & PW & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & PD).
  assert (FIN : forall (fx' : FPState) R' M', PML.fp_ok fx' -> getr R' 2%bv = Z_to_bv 64 sp -> TK.keepsR CK.CSR R0 R' ->
            TK.samem (fun a => ~ (sp - 80 <= a < sp)) M0 M' -> mem_grows M0 M' -> (forall w, PMW.win_bytes M' ps0 w -> w = []) ->
            srealizes RSEGS SCFG (@PML.cfg fx' R' r M' model0) K).
  { intros fx' R' M' Hfp' H2' Hk' Hsm Hg Hw0.
    assert (HS' : sinv M' model0 cr ps0) by exact (sinv_stack M0 M' model0 cr ps0 (sp - 80) sp HS Hsm Hg ltac:(lia) ltac:(lia)).
    assert (HWV' : winv M' ps0).
    { apply (winv_x M0 M' model0 cr ps0 (fun a => ~ (sp - 80 <= a < sp)) HS HWV Hsm).
      - intros a Ha. cbv beta. lia.
      - intros a Ha. unfold PKW.tokc in Ha. cbv beta. lia. }
    apply (finish fx' R' M' model0 cr ps0 Hfp' (conj HS' HWV')).
    - intros c w HWB _. rewrite (Hw0 w HWB). reflexivity.
    - apply CK.rp_of_keeps; [rewrite H2', R0sp; reflexivity | exact Hk']. }
  destruct (PML.ps_win ps0) as [[p e]|] eqn:Hw.
  - destruct PW as (P200 & P192 & Ple).
    pose proof HWIN as HW0. unfold PML.win_ok in HW0. rewrite Hw in HW0. destruct HW0 as (ch & Hin & Hc1 & Hc2 & Hdef).
    pose proof (blk0 _ _ _ _ HH _ (in_or_app _ _ _ (or_intror Hin))) as (B0 & B1 & B2). cbn [fst snd] in B0, B1, B2.
    apply (SWS.s_sw_entry FPM fx R0 M0 model0 K sp P p e r MO1 MO2 Hfp R0sp spok H1 Prok H10).
    all: try lia.
    all: first [exact P192 | exact P200 | (eapply (L5.defined_sub _ _ _ _ _ SD); lia) | idtac].
    + intros Hpe fx' R' M' Hfp' H2' Hk' Hsm Hg. apply (FIN fx' R' M' Hfp' H2' Hk' Hsm Hg).
      intros w HWB. unfold PMW.win_bytes in HWB. rewrite Hw in HWB. destruct HWB as (_ & HL & _). destruct w; [reflexivity | cbn [length] in HL; lia].
    + intros Hpe fx' R' M' Hfp' H2' Hlive H10' Hfr Hko Hsm Hg.
      assert (Hlt : p < e) by lia.
      assert (Hm : PML.ps_more ps0 = false).
      { destruct (PML.ps_more ps0) eqn:Em; [|reflexivity]. exfalso. pose proof (Hex eq_refl) as X. unfold PMS.win_exhausted in X. rewrite Hw in X. lia. }
      assert (HS' : sinv M' model0 cr ps0) by exact (sinv_stack M0 M' model0 cr ps0 (sp - 80) sp HS Hsm Hg ltac:(lia) ltac:(lia)).
      assert (HWV' : winv M' ps0).
      { apply (winv_x M0 M' model0 cr ps0 (fun a => ~ (sp - 80 <= a < sp)) HS HWV Hsm).
        - intros a Ha. cbv beta. lia.
        - intros a Ha. unfold PKW.tokc in Ha. cbv beta. lia. }
      assert (Hmu0 : mu ps0 p e <= Z.of_nat (Z.to_nat (mu ps0 p e))) by (rewrite Z2Nat.id; [lia | unfold mu; destruct (Z.eqb (PML.ps_st ps0) 28); lia]).
      exact (loop_all (Z.to_nat (mu ps0 p e)) fx' R' M' model0 cr ps0 p e Hmu0 Hw Hlt Hfp' (conj HS' HWV') Hm H2' Hlive H10' Hfr Hko).
  - destruct PW as (P192 & P200).
    apply (SWS.s_sw_entry FPM fx R0 M0 model0 K sp P 0 0 r MO1 MO2 Hfp R0sp spok H1 Prok H10).
    all: try lia.
    all: first [exact P192 | exact P200 | (eapply (L5.defined_sub _ _ _ _ _ SD); lia) | idtac].
    + intros _ fx' R' M' Hfp' H2' Hk' Hsm Hg. apply (FIN fx' R' M' Hfp' H2' Hk' Hsm Hg).
      intros w HWB. unfold PMW.win_bytes in HWB. rewrite Hw in HWB. exact HWB.
Qed.
